// 🔑 KONFIGURASI MAYAR — ganti dengan data dari dashboard Mayar lo
// (Dashboard Mayar -> Pengaturan -> API / Token)
const MAYAR_API_TOKEN = 'API-TOKEN-LO-DISINI';

// 🏷️ PRODUCT ID — WAJIB:
// 1. Login dashboard Mayar -> Produk -> Tambah Produk
// 2. Bikin produk: "Workshop Closing Naik dengan AI" (Rp 299.000)
// 3. Copy ID produk-nya, tempel di sini
const PRODUCT_ID = 'PRODUCT-ID-LO-DISINI';

// URL callback (harus HTTPS & bisa diakses publik)
// = URL webhook yang akan diisi di dashboard Mayar:
// Dashboard Mayar -> Pengaturan -> Webhook -> Payment Callback URL
const CALLBACK_URL = 'https://n8n.43-133-131-126.sslip.io/webhook/mayar-callback';

// URL return (ke halaman status di Vercel)
const RETURN_URL = 'https://VERCEL_DOMAIN_LO_DISINI/success.html';

// Endpoint Mayar
const MAYAR_ENDPOINT = 'https://api.mayar.id/hl/v1/checkout';

// Data dari checkout page
const body = $input.first().json.body || {};
const nama = (body.nama || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const wa = (body.wa || '').toString().trim();

// Validasi minimal
if (!nama || !email || !wa) {
  throw new Error('Data tidak lengkap: nama, email, dan WA wajib diisi');
}

// Nomor HP untuk Mayar (format 08..., min 10 digit)
const mobile = wa.replace(/[^0-9]/g, '');
if (mobile.length < 10) {
  throw new Error('Nomor WA tidak valid (minimal 10 digit)');
}

// Payload ke Mayar
const payload = {
  name: nama,
  email: email,
  mobile: mobile,
  paymentType: 'QRIS',   // GANTI sesuai channel Mayar: QRIS / VA / dll
  productId: PRODUCT_ID,
  callbackUrl: CALLBACK_URL,
  returnUrl: RETURN_URL
};

return {
  json: {
    endpoint: MAYAR_ENDPOINT,
    token: MAYAR_API_TOKEN,
    payload: payload
  }
};

// Response dari Mayar — struktur: { statusCode, messages, data }
const mayarResp = $input.first().json;

// Cek error
if (mayarResp.statusCode && mayarResp.statusCode >= 400) {
  throw new Error('Mayar error: ' + JSON.stringify(mayarResp));
}

const data = mayarResp.data || {};

// Mayar checkout response — field payment URL bisa bervariasi.
// Cek di response asli lo, lalu samakan field-nya di bawah.
const paymentUrl = data.payment_url || data.url || data.checkout_url || data.redirect_url || '';

if (!paymentUrl) {
  // Kalau response belum punya URL (misal butuh step tambahan),
  // log semua data biar kelihatan strukturnya:
  throw new Error('payment_url tidak ditemukan. Response Mayar: ' + JSON.stringify(mayarResp));
}

return {
  json: {
    payment_url: paymentUrl,
    reference: data.reference || data.id || data.payment_ref || '',
    amount: data.amount || 299000
  }
};
